import re
from typing import List, Optional, Tuple, Dict, Any

def _split_logical_records(text: str) -> List[str]:
    records = []
    current = []
    quote = None
    field_start = True
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if quote is None:
            if field_start and ch in ('"', "'"):
                quote = ch
                field_start = False
                current.append(ch)
            elif ch == ',':
                current.append(ch)
                field_start = True
            elif ch == '\n' or ch == '\r':
                if ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                    i += 1
                record = ''.join(current)
                if record.strip():
                    records.append(record)
                current = []
                field_start = True
            else:
                current.append(ch)
                if ch not in ' \t':
                    field_start = False
        else:
            current.append(ch)
            if ch == quote:
                if i + 1 < n and text[i + 1] == quote:
                    current.append(text[i + 1])
                    i += 1
                else:
                    j = i + 1
                    while j < n and text[j] in ' \t':
                        j += 1
                    if j >= n or text[j] in ',\r\n':
                        quote = None
            elif ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                pass

        i += 1

    if current:
        record = ''.join(current)
        if record.strip():
            records.append(record)

    return records

def _parse_record(record: str) -> List[str]:
    fields = []
    current = []
    quote = None
    field_start = True
    i = 0
    n = len(record)

    while i < n:
        ch = record[i]

        if quote is None:
            if field_start and ch in ('"', "'"):
                quote = ch
                field_start = False
            elif ch == ',':
                fields.append(''.join(current))
                current = []
                field_start = True
            else:
                current.append(ch)
                if ch not in ' \t':
                    field_start = False
        else:
            if ch == quote:
                if i + 1 < n and record[i + 1] == quote:
                    current.append(quote)
                    i += 1
                else:
                    j = i + 1
                    while j < n and record[j] in ' \t':
                        j += 1
                    if j >= n or record[j] == ',':
                        quote = None
                    else:
                        current.append(ch)
            else:
                current.append(ch)

        i += 1

    fields.append(''.join(current).rstrip('\r'))
    return fields

def _header_score(fields: List[str]) -> int:
    score = 0
    for value in fields:
        token = value.strip().lower()
        if not token:
            continue
        if token in ('date', 'time', 'qty', 'quantity', 'price', 'comments',
                     'comment', 'url', 'productid', 'producttype',
                     'productdescription', 'description'):
            score += 3
        elif any(word in token for word in
                 ('date', 'time', 'product', 'price', 'comment', 'url', 'qty')):
            score += 1
    return score

def _normalize_width(row: List[str], width: int) -> List[str]:
    if len(row) == width:
        return row
    if len(row) < width:
        return row + [''] * (width - len(row))
    if width <= 1:
        return [','.join(row)]
    return row[:width - 1] + [','.join(row[width - 1:])]

def parse_csv(raw_csv: str):
    records = _split_logical_records(raw_csv)
    parsed = [_parse_record(record) for record in records]
    parsed = [row for row in parsed if row and any(cell.strip() for cell in row)]

    if not parsed:
        return {"columns": [], "rows": []}

    width_counts: Dict[int, int] = {}
    for row in parsed:
        width_counts[len(row)] = width_counts.get(len(row), 0) + 1
    modal_width = max(width_counts, key=width_counts.get)

    header_index = 0
    best_score = -1
    for index, row in enumerate(parsed):
        score = _header_score(row)
        if score > best_score:
            best_score = score
            header_index = index

    if best_score <= 0:
        candidates = [
            (index, row) for index, row in enumerate(parsed)
            if len(row) == modal_width
        ]
        if candidates:
            header_index = candidates[0][0]

    header = parsed[header_index]
    width = len(header)
    if width == 0:
        return {"columns": [], "rows": []}

    columns = [value.strip() for value in header]
    rows = []
    for row in parsed[header_index + 1:]:
        normalized = _normalize_width(row, width)
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
